<article class="event-card"><a class="event-art event-art-{{ $event['tone'] ?? 'coral' }}" href="{{ route('events.show', $event['id']) }}" tabindex="-1" aria-hidden="true"><span class="art-orbit art-orbit-one"></span><span class="art-orbit art-orbit-two"></span><span class="art-symbol">{{ $event['symbol'] ?? '✳' }}</span><span class="art-label">{{ $event['category'] }}</span></a><div class="event-card-body"><div class="event-card-date"><span class="date-day">{{ \Carbon\Carbon::parse($event['starts_at'])->format('d') }}</span><span class="date-month">{{ \Carbon\Carbon::parse($event['starts_at'])->translatedFormat('M') }}</span><span class="date-time">{{ \Carbon\Carbon::parse($event['starts_at'])->format('H:i') }}</span></div><div class="event-card-copy"><p class="card-category">{{ $event['category'] }}</p><h3><a href="{{ route('events.show', $event['id']) }}">{{ $event['title'] }}</a></h3><p class="card-location"><span aria-hidden="true">⌖</span> {{ $event['location'] }}</p></div><div class="card-footer"><span class="availability"><span class="availability-dot"></span>{{ $event['remaining'] }} places disponibles</span><a class="arrow-link" href="{{ route('events.show', $event['id']) }}" aria-label="Voir {{ $event['title'] }}">↗</a></div></div></article>
